[et_pb_section fb_built="1" admin_label="RM Hero" _builder_version="4.27.4" use_custom_width="on" width_unit="off" custom_width_px="100%" custom_padding="0px||0px||false|false" global_colors_info="{}"][et_pb_row _builder_version="4.27.4" width="100%" max_width="100%" use_custom_gutter="on" gutter_width="1" custom_padding="0px||0px||false|false" global_colors_info="{}"][et_pb_column type="4_4" _builder_version="4.27.4" global_colors_info="{}"][et_pb_code admin_label="RM Hero — Code" _builder_version="4.27.4" global_colors_info="{}"]<!-- ============================================================
     RM HERO — Sección hero profesional para Divi 5 (Code Module)
     Marca: Rodmedia (premium)
     Estructura: eyebrow + H1 + subtítulo + CTA primario/secundario
     + indicadores de confianza + visual (mockup CSS, sin imágenes
     externas) con micro-animación al cargar y al hacer scroll.

     ANTES DE PUBLICAR:
     1) Sustituye las cifras de "rm-hero__trust" por datos reales.
     2) Cambia los href de los CTA por tus anclas/páginas reales.
     3) Si ya cargas Fraunces / Plus Jakarta Sans desde el Theme
        Builder de Divi, borra el @import de más abajo para evitar
        cargarlas dos veces (mejor rendimiento).
     ============================================================ -->

<section class="rm-hero" aria-label="Presentación de Rodmedia">

  <div class="rm-hero__bg" aria-hidden="true">
    <div class="rm-hero__glow rm-hero__glow--a"></div>
    <div class="rm-hero__glow rm-hero__glow--b"></div>
    <div class="rm-hero__grid"></div>
  </div>

  <div class="rm-hero__container">

    <div class="rm-hero__content" data-animate>
      <span class="rm-hero__eyebrow">
        <span class="rm-hero__eyebrow-dot" aria-hidden="true"></span>
        Agencia creativa · Comunitat Valenciana
      </span>

      <h1 class="rm-hero__title">
        Diseñamos marcas y webs <em>con alma</em> para negocios que quieren dar el salto
      </h1>

      <p class="rm-hero__subtitle">
        Estrategia, diseño y desarrollo en un mismo equipo. Proyectos a medida
        para negocios que ya funcionan y quieren verse — y venderse — a la altura.
      </p>

      <div class="rm-hero__actions">
        <a href="#contacto" class="rm-hero__cta rm-hero__cta--primary">
          Quiero mi proyecto a medida
        </a>
        <a href="#casos" class="rm-hero__cta rm-hero__cta--secondary">
          Ver casos de éxito
          <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden="true">
            <path d="M3.5 8h9M8.5 3.5 13 8l-4.5 4.5" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
          </svg>
        </a>
      </div>

      <dl class="rm-hero__trust">
        <div class="rm-hero__trust-item">
          <dt class="rm-hero__trust-number">+40</dt>
          <dd class="rm-hero__trust-label">proyectos entregados</dd>
        </div>
        <div class="rm-hero__trust-item">
          <dt class="rm-hero__trust-number">9.8/10</dt>
          <dd class="rm-hero__trust-label">satisfacción de cliente</dd>
        </div>
        <div class="rm-hero__trust-item">
          <dt class="rm-hero__trust-number">15</dt>
          <dd class="rm-hero__trust-label">días de media hasta el lanzamiento</dd>
        </div>
      </dl>
    </div>

    <div class="rm-hero__visual" data-animate>
      <div class="rm-hero__mock" role="img" aria-label="Vista previa de una web diseñada por Rodmedia">
        <div class="rm-hero__mock-bar">
          <span></span><span></span><span></span>
        </div>
        <div class="rm-hero__mock-body">
          <div class="rm-hero__mock-line rm-hero__mock-line--title"></div>
          <div class="rm-hero__mock-line rm-hero__mock-line--text"></div>
          <div class="rm-hero__mock-line rm-hero__mock-line--text rm-hero__mock-line--short"></div>
          <div class="rm-hero__mock-cta"></div>
          <div class="rm-hero__mock-grid">
            <span></span><span></span><span></span>
          </div>
        </div>
      </div>

      <div class="rm-hero__badge">
        <svg width="18" height="18" viewBox="0 0 18 18" fill="none" aria-hidden="true">
          <circle cx="9" cy="9" r="9" fill="var(--rm-accent)"/>
          <path d="M5.5 9.2 7.7 11.4 12.5 6.6" stroke="var(--rm-primary)" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/>
        </svg>
        <div>
          <strong>Proyecto entregado</strong>
          <span>Hace 3 días</span>
        </div>
      </div>
    </div>

  </div>
</section>

<style>
  @import url('https://fonts.googleapis.com/css2?family=Fraunces:ital,opsz,wght@0,9..144,500;0,9..144,600;1,9..144,500&family=Plus+Jakarta+Sans:wght@400;500;600;700&display=swap');

  .rm-hero {
    --rm-primary: #1a1a2e;
    --rm-primary-deep: #101019;
    --rm-accent: #e8934a;
    --rm-light: #f8f6f2;
    --rm-text: var(--rm-light);
    --rm-text-muted: #a9adc1;
    --rm-radius: 8px;
    --rm-radius-lg: 20px;
    --rm-shadow: 0 24px 60px rgba(0, 0, 0, 0.35);
    --rm-transition: 0.3s ease;
    --rm-font-display: "Fraunces", Georgia, "Times New Roman", serif;
    --rm-font-body: "Plus Jakarta Sans", -apple-system, BlinkMacSystemFont, sans-serif;

    position: relative;
    overflow: hidden;
    background: radial-gradient(120% 120% at 15% 10%, var(--rm-primary) 0%, var(--rm-primary-deep) 65%);
    color: var(--rm-text);
    font-family: var(--rm-font-body);
    padding: 120px 20px 100px;
    box-sizing: border-box;
  }

  .rm-hero *,
  .rm-hero *::before,
  .rm-hero *::after {
    box-sizing: inherit;
  }

  /* ---------- Fondo decorativo ---------- */
  .rm-hero__bg {
    position: absolute;
    inset: 0;
    pointer-events: none;
    z-index: 0;
  }

  .rm-hero__glow {
    position: absolute;
    border-radius: 50%;
    filter: blur(80px);
    opacity: 0.35;
    animation: rm-hero-float 12s ease-in-out infinite;
  }

  .rm-hero__glow--a {
    width: 480px;
    height: 480px;
    top: -160px;
    right: -120px;
    background: var(--rm-accent);
  }

  .rm-hero__glow--b {
    width: 360px;
    height: 360px;
    bottom: -140px;
    left: -80px;
    background: #3d3d6b;
    animation-delay: -6s;
  }

  .rm-hero__grid {
    position: absolute;
    inset: 0;
    background-image: linear-gradient(rgba(255, 255, 255, 0.04) 1px, transparent 1px),
      linear-gradient(90deg, rgba(255, 255, 255, 0.04) 1px, transparent 1px);
    background-size: 48px 48px;
    mask-image: radial-gradient(80% 60% at 50% 30%, #000 40%, transparent 100%);
  }

  @keyframes rm-hero-float {
    0%, 100% { transform: translateY(0) scale(1); }
    50% { transform: translateY(24px) scale(1.05); }
  }

  /* ---------- Contenedor ---------- */
  .rm-hero__container {
    position: relative;
    z-index: 1;
    max-width: 1140px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: 1.05fr 0.95fr;
    align-items: center;
    gap: 64px;
  }

  /* ---------- Contenido ---------- */
  .rm-hero__content[data-animate],
  .rm-hero__visual[data-animate] {
    opacity: 0;
    transform: translateY(24px);
    transition: opacity 0.7s ease, transform 0.7s ease;
  }

  .rm-hero__content.is-visible,
  .rm-hero__visual.is-visible {
    opacity: 1;
    transform: translateY(0);
  }

  .rm-hero__visual[data-animate] {
    transition-delay: 0.15s;
  }

  .rm-hero__eyebrow {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 8px 16px;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid rgba(255, 255, 255, 0.1);
    font-size: 13px;
    font-weight: 600;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: var(--rm-text-muted);
    margin-bottom: 24px;
  }

  .rm-hero__eyebrow-dot {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: var(--rm-accent);
  }

  .rm-hero__title {
    font-family: var(--rm-font-display);
    font-weight: 600;
    font-size: clamp(2.25rem, 1.4rem + 3.4vw, 3.75rem);
    line-height: 1.12;
    letter-spacing: -0.01em;
    margin: 0 0 20px;
    color: var(--rm-light);
  }

  .rm-hero__title em {
    font-style: italic;
    color: var(--rm-accent);
  }

  .rm-hero__subtitle {
    font-size: 17px;
    line-height: 1.7;
    color: var(--rm-text-muted);
    max-width: 46ch;
    margin: 0 0 36px;
  }

  /* ---------- CTAs ---------- */
  .rm-hero__actions {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 20px;
    margin-bottom: 56px;
  }

  .rm-hero__cta {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    font-family: var(--rm-font-body);
    font-size: 15px;
    font-weight: 600;
    text-decoration: none;
    border-radius: var(--rm-radius);
    transition: transform var(--rm-transition), box-shadow var(--rm-transition),
      border-color var(--rm-transition), opacity var(--rm-transition);
  }

  .rm-hero__cta--primary {
    padding: 16px 28px;
    background: var(--rm-accent);
    color: var(--rm-primary);
    box-shadow: 0 12px 28px rgba(232, 147, 74, 0.28);
  }

  .rm-hero__cta--primary:hover {
    transform: translateY(-2px);
    box-shadow: 0 16px 32px rgba(232, 147, 74, 0.38);
  }

  .rm-hero__cta--secondary {
    padding: 16px 4px;
    color: var(--rm-light);
    border-bottom: 1px solid rgba(255, 255, 255, 0.25);
  }

  .rm-hero__cta--secondary svg {
    transition: transform var(--rm-transition);
  }

  .rm-hero__cta--secondary:hover {
    border-color: var(--rm-accent);
    color: var(--rm-accent);
  }

  .rm-hero__cta--secondary:hover svg {
    transform: translateX(4px);
  }

  /* ---------- Indicadores de confianza ---------- */
  .rm-hero__trust {
    display: flex;
    flex-wrap: wrap;
    gap: 32px;
    margin: 0;
    padding-top: 32px;
    border-top: 1px solid rgba(255, 255, 255, 0.1);
  }

  .rm-hero__trust-item {
    display: flex;
    flex-direction: column;
    gap: 4px;
  }

  .rm-hero__trust-number {
    font-family: var(--rm-font-display);
    font-size: 26px;
    font-weight: 600;
    color: var(--rm-light);
  }

  .rm-hero__trust-label {
    margin: 0;
    font-size: 13px;
    color: var(--rm-text-muted);
  }

  /* ---------- Visual: mockup de web ---------- */
  .rm-hero__visual {
    position: relative;
  }

  .rm-hero__mock {
    background: rgba(255, 255, 255, 0.04);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: var(--rm-radius-lg);
    box-shadow: var(--rm-shadow);
    backdrop-filter: blur(12px);
    overflow: hidden;
  }

  .rm-hero__mock-bar {
    display: flex;
    gap: 6px;
    padding: 16px 20px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  }

  .rm-hero__mock-bar span {
    width: 10px;
    height: 10px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.15);
  }

  .rm-hero__mock-bar span:first-child {
    background: var(--rm-accent);
  }

  .rm-hero__mock-body {
    padding: 32px 28px 36px;
  }

  .rm-hero__mock-line {
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.1);
  }

  .rm-hero__mock-line--title {
    width: 70%;
    height: 18px;
    margin-bottom: 16px;
    background: linear-gradient(90deg, var(--rm-accent), rgba(232, 147, 74, 0.3));
  }

  .rm-hero__mock-line--text {
    width: 100%;
    height: 10px;
    margin-bottom: 10px;
  }

  .rm-hero__mock-line--short {
    width: 60%;
    margin-bottom: 24px;
  }

  .rm-hero__mock-cta {
    width: 140px;
    height: 36px;
    border-radius: var(--rm-radius);
    background: var(--rm-accent);
    margin-bottom: 28px;
  }

  .rm-hero__mock-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 12px;
  }

  .rm-hero__mock-grid span {
    display: block;
    height: 64px;
    border-radius: var(--rm-radius);
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid rgba(255, 255, 255, 0.08);
  }

  /* ---------- Tarjeta flotante (social proof) ---------- */
  .rm-hero__badge {
    position: absolute;
    left: -24px;
    bottom: -28px;
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 14px 20px;
    background: rgba(26, 26, 46, 0.85);
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: var(--rm-radius-lg);
    box-shadow: 0 16px 40px rgba(0, 0, 0, 0.4);
    backdrop-filter: blur(14px);
    animation: rm-hero-bob 5s ease-in-out infinite;
  }

  .rm-hero__badge strong {
    display: block;
    font-size: 13px;
    color: var(--rm-light);
  }

  .rm-hero__badge span {
    font-size: 12px;
    color: var(--rm-text-muted);
  }

  @keyframes rm-hero-bob {
    0%, 100% { transform: translateY(0); }
    50% { transform: translateY(-8px); }
  }

  @media (prefers-reduced-motion: reduce) {
    .rm-hero__glow,
    .rm-hero__badge {
      animation: none;
    }

    .rm-hero__content[data-animate],
    .rm-hero__visual[data-animate] {
      opacity: 1;
      transform: none;
      transition: none;
    }
  }

  /* ---------- Responsive ---------- */
  @media (max-width: 980px) {
    .rm-hero {
      padding: 90px 20px 60px;
    }

    .rm-hero__container {
      grid-template-columns: 1fr;
      gap: 56px;
    }

    .rm-hero__visual {
      order: -1;
      max-width: 440px;
      margin: 0 auto;
    }

    .rm-hero__subtitle {
      max-width: 60ch;
    }
  }

  @media (max-width: 767px) {
    .rm-hero {
      padding: 64px 16px 40px;
    }

    .rm-hero__title {
      font-size: clamp(2rem, 1.5rem + 4vw, 2.5rem);
    }

    .rm-hero__actions {
      flex-direction: column;
      align-items: flex-start;
      gap: 16px;
      margin-bottom: 40px;
    }

    .rm-hero__cta--primary {
      width: 100%;
      justify-content: center;
    }

    .rm-hero__trust {
      gap: 20px;
    }

    .rm-hero__badge {
      left: 16px;
      right: 16px;
      bottom: -20px;
    }
  }
</style>

<script>
  (function () {
    var elements = document.querySelectorAll(".rm-hero [data-animate]");
    if (!("IntersectionObserver" in window) || !elements.length) {
      elements.forEach(function (el) { el.classList.add("is-visible"); });
      return;
    }
    var observer = new IntersectionObserver(
      function (entries) {
        entries.forEach(function (entry) {
          if (entry.isIntersecting) {
            entry.target.classList.add("is-visible");
            observer.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.15 }
    );
    elements.forEach(function (el) { observer.observe(el); });
  })();
</script>
